# Read dimensions (current records only for SCD Type 2)
df_customer = spark.table(Config.TBL_DIM_CUSTOMER).filter(col(Config.SCD_IS_CURRENT_COL) == 1)
df_product = spark.table(Config.TBL_DIM_PRODUCT)
