# COMMAND ----------

# DBTITLE 1,Build FactSales with Surrogate Keys
# Left joins to get surrogate keys (use -1 for orphans)
# Bronze table uses natural keys (CustomerName, ProductName, etc.)

# Prepare date dimensions with unique aliases (if date dimension exists)
if date_exists and df_date is not None:
    df_date_order = df_date.select(col("DateID").alias("OrderDateID"), col("Date").alias("OrderDateKey"))
    df_date_mfd = df_date.select(col("DateID").alias("MFDDateID"), col("Date").alias("MFDDateKey"))
    df_date_exp = df_date.select(col("DateID").alias("EXPDateID"), col("Date").alias("EXPDateKey"))
    df_date_delivery = df_date.select(col("DateID").alias("DeliveryDateID"), col("Date").alias("DeliveryDateKey"))

# Build fact table with conditional joins
df_fact = df_stg \
    .join(df_customer.select("CustomerSK", "CustomerName"), on="CustomerName", how="left") \
    .join(df_product.select("ProductSK", "ProductName"), on="ProductName", how="left") \
    .join(df_warehouse.select("WarehouseSK", "WarehouseName").withColumnRenamed("WarehouseName", "WareHouseName"), on="WareHouseName", how="left") \
    .join(df_retailer.select("RetailerSK", "RetailerName"), on="RetailerName", how="left") \
    .join(df_product_category.select("ProductCategorySK", "ProductCategory"), on="ProductCategory", how="left")

# Conditional joins for optional dimensions
if agent_exists and df_agent is not None:
    df_fact = df_fact.join(
        df_agent.select("AgentSK", "AgentName"), 
        on="AgentName", 
        how="left"
    )
else:
    # Add placeholder column if dimension doesn't exist
    df_fact = df_fact.withColumn("AgentSK", lit(-1))

if payment_exists and df_payment is not None:
    df_fact = df_fact.join(
        df_payment.select("PaymentModeSK", "PaymentMode"), 
        on="PaymentMode", 
        how="left"
    )
else:
    # Add placeholder column if dimension doesn't exist
    df_fact = df_fact.withColumn("PaymentModeSK", lit(-1))

if date_exists and df_date is not None:
    df_fact = df_fact \
        .join(df_date_order, to_date(col("OrderDate")) == col("OrderDateKey"), how="left") \
        .join(df_date_mfd, to_date(col("MFDDate")) == col("MFDDateKey"), how="left") \
        .join(df_date_exp, to_date(col("EXPDate")) == col("EXPDateKey"), how="left") \
        .join(df_date_delivery, to_date(col("DeliveryDate")) == col("DeliveryDateKey"), how="left")

# Build final fact table with proper column selection
df_fact = df_fact.select(
    col("OrderID").cast("bigint"),
    coalesce(col("CustomerSK"), lit(-1)).alias("CustomerSK"),
    coalesce(col("ProductSK"), lit(-1)).alias("ProductSK"),
    coalesce(col("WarehouseSK"), lit(-1)).alias("WarehouseSK"),
    coalesce(col("RetailerSK"), lit(-1)).alias("RetailerSK"),
    coalesce(col("AgentSK"), lit(-1)).alias("AgentSK"),
    coalesce(col("PaymentModeSK"), lit(-1)).alias("PaymentModeSK"),
    coalesce(col("ProductCategorySK"), lit(-1)).alias("ProductCategorySK"),
    coalesce(col("OrderDateID"), lit(-1)).alias("OrderDateID") if date_exists else lit(-1).alias("OrderDateID"),
    coalesce(col("MFDDateID"), lit(-1)).alias("MFDDateID") if date_exists else lit(-1).alias("MFDDateID"),
    coalesce(col("EXPDateID"), lit(-1)).alias("EXPDateID") if date_exists else lit(-1).alias("EXPDateID"),
    coalesce(col("DeliveryDateID"), lit(-1)).alias("DeliveryDateID") if date_exists else lit(-1).alias("DeliveryDateID"),
    col("ProductQuantity").cast("int"),
    col("CostPrice").cast("decimal(10,2)"),
    col("sellingPrice").cast("decimal(10,2)"),
    col("discount").cast("decimal(10,2)"),
    col("finalprice").cast("decimal(10,2)"),
    col("CGST").cast("decimal(10,2)"),
    col("SGST").cast("decimal(10,2)"),
    col(Config.COL_BATCH_DATE),
    col(Config.COL_LOADED_AT)
)

fact_count = df_fact.count()
print("="*70)
print("FACT TABLE CONSTRUCTION")
print("="*70)
print(f"✅ Built fact table with {fact_count:,} rows")
print(f"📌 Orphan Handling: coalesce(col, -1) defaults missing keys to -1 (Unknown)")
print("="*70)

