    print("➕ INCREMENTAL MODE: Appending new batch")
    df_fact.write.mode("append").format("delta").saveAsTable(Config.TBL_FACT_SALES)
    print(f"\n✅ INCREMENTAL LOAD completed")
    print(f"   Records appended: {fact_count:,}")
    print(f"   Mode: APPEND (additive)")

