query = f"""
SELECT 
    COUNT(*) AS transaction_count,
    ROUND(SUM(finalprice) / 10000000, 2) AS revenue_crores,
    ROUND(AVG(finalprice), 2) AS avg_transaction_value,
    ROUND(MIN(finalprice), 2) AS min_transaction,
    ROUND(MAX(finalprice), 2) AS max_transaction
FROM {Config.TBL_FACT_SALES}
{where_clause}
"""

