# DBTITLE 1,Validation 3 - Row Count Match (Source vs Fact)
# Validate that fact_sales has same row count as staging (no data loss)
# Scope based on load_type
if load_type == "incremental":
    source_table = Config.TBL_STG_SALES_INCREMENTAL
    source_where = f"WHERE {Config.COL_BATCH_DATE} = '{batch_date}'"
    fact_where = f"WHERE {Config.COL_BATCH_DATE} = '{batch_date}'"
    scope_msg = f"INCREMENTAL VALIDATION: Comparing batch {batch_date}"
else:
    source_table = Config.TBL_STG_SALES
    source_where = f"WHERE {Config.COL_BATCH_DATE} >= '{load_since}'"
    fact_where = f"WHERE {Config.COL_BATCH_DATE} >= '{load_since}'"
    scope_msg = f"FULL VALIDATION: Comparing all records since {load_since}"

query = f"""
WITH source_count AS (
    SELECT COUNT(*) AS source_rows
    FROM {source_table}
    {source_where}
),
fact_count AS (
    SELECT COUNT(*) AS fact_rows
    FROM {Config.TBL_FACT_SALES}
    {fact_where}
)
SELECT 
    s.source_rows,
    f.fact_rows,
    (f.fact_rows - s.source_rows) AS difference,
    CASE 
        WHEN f.fact_rows = s.source_rows THEN '✅ PASS - Row counts match'
        WHEN f.fact_rows < s.source_rows THEN '❌ FAIL - Missing rows in fact table'
        ELSE '⚠️ WARNING - Fact table has more rows than source'
    END AS validation_status
FROM source_count s, fact_count f
"""

print("="*70)
print("VALIDATION 3: ROW COUNT MATCH")
print("="*70)
print(scope_msg)
print(f"Source: {source_table}")
print(f"Target: {Config.TBL_FACT_SALES}")
print("="*70)

display(spark.sql(query))